"""Independent interior-point replay of exact archived grounded COP inequalities."""
import argparse,datetime,hashlib,json
from pathlib import Path
import clarabel,numpy as np,scipy.sparse as sp
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--directory',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();P=sp.load_npz(a.directory/'failed_P.npz');A=sp.load_npz(a.directory/'failed_A.npz');v=np.load(a.directory/'failed_vectors.npz');q=v['gradient'];l=v['lower'];u=v['upper'];cs=v['column_scale'];rs=v['row_scale'];scale=float(v['objective_scale']);C=sp.diags(cs);D=sp.diags(rs);B=(D@A@C).tocsc();upper=np.flatnonzero(np.isfinite(u));lower=np.flatnonzero(np.isfinite(l));M=sp.vstack([B[upper],-B[lower]],format='csc');b=np.r_[rs[upper]*u[upper],-rs[lower]*l[lower]];settings=clarabel.DefaultSettings();settings.verbose=False;settings.max_iter=200;settings.tol_feas=1e-8;settings.tol_gap_abs=1e-8;settings.tol_gap_rel=1e-8;solver=clarabel.DefaultSolver(sp.triu(C@P@C/scale,format='csc'),cs*q/scale,M,b,[clarabel.NonnegativeConeT(len(b))],settings);result=solver.solve();step=cs*np.array(result.x);violation=float(max(0,(l-A@step).max(),(A@step-u).max()));dual=np.zeros(len(l));z=np.array(result.z);dual[upper]+=scale*rs[upper]*z[:len(upper)];dual[lower]-=scale*rs[lower]*z[len(upper):];stationarity=P@step+q+A.T@dual;kkt=float(np.linalg.norm(stationarity,np.inf)/max(1,np.linalg.norm(P@step,np.inf),np.linalg.norm(q,np.inf),np.linalg.norm(A.T@dual,np.inf)));np.savez_compressed(a.output.parent/'clarabel_same_qp_step.npz',step=step,dual=dual);out=dict(time_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Exact archived P/A/q/inequalities, same scales/objective. Different independent solver with fixed200interior-point iterations; no nonlinear or physics acceptance.',solver_version=clarabel.__version__,status=str(result.status),iterations=result.iterations,unscaled_constraint_violation=violation,original_relative_stationarity=kkt,original_gate_pass=bool(str(result.status)=='Solved' and violation<=1e-7 and kkt<=1e-7),objective=float(.5*step@(P@step)+q@step),solve_time_seconds=result.solve_time,primal_residual=result.r_prim,dual_residual=result.r_dual,source_hashes={name:hashlib.sha256((a.directory/name).read_bytes()).hexdigest() for name in ['failed_P.npz','failed_A.npz','failed_vectors.npz']});a.output.write_text(json.dumps(out,indent=2)+'\n');print(out,flush=True)
